    /// Vim's `utf_class()` for one code point.
    static func vimClass(of scalar: Unicode.Scalar) -> Int {
        var low = 0
        var high = ranges.count - 1
        while low <= high {
            let middle = (low + high) / 2
            let range = ranges[middle]
            if scalar.value < range.first {
                high = middle - 1
            } else if scalar.value > range.last {
                low = middle + 1
            } else {
                return range.vimClass
            }
        }
        return 2
    }
